#!/usr/bin/env python3
"""Ink analysis: find bbox of pixels differing from a reference image, or from a bg color."""
import sys, collections
sys.path.insert(0, '/workspace/notes')
import pngtool

def diffbox(a, b):
    i1 = pngtool.load(a); i2 = pngtool.load(b)
    w, h = i1[0], i1[1]
    if (i1[0], i1[1]) != (i2[0], i2[1]):
        print("SIZE DIFFERS %dx%d vs %dx%d" % (i1[0], i1[1], i2[0], i2[1])); return
    xs = []; ys = []
    rows = collections.defaultdict(list)
    for y in range(h):
        for x in range(w):
            if pngtool.px(i1, x, y) != pngtool.px(i2, x, y):
                xs.append(x); ys.append(y); rows[y].append(x)
    if not xs: print("identical"); return
    print("bbox x=%d..%d (w=%d) y=%d..%d (h=%d) n=%d imgw=%d imgh=%d" % (
        min(xs), max(xs), max(xs)-min(xs)+1, min(ys), max(ys), max(ys)-min(ys)+1, len(xs), w, h))
    print("x-center=%.1f imgcenter=%.1f  ycenter=%.1f" % ((min(xs)+max(xs))/2, (w-1)/2, (min(ys)+max(ys))/2))
    for y in sorted(rows):
        print("  y=%d: x=%d..%d n=%d" % (y, min(rows[y]), max(rows[y]), len(rows[y])))

def inkbox(f, bg, x0=None, y0=None, x1=None, y1=None):
    """bbox of pixels != bg hex within region"""
    img = pngtool.load(f); w, h = img[0], img[1]
    x0 = 0 if x0 is None else x0; y0 = 0 if y0 is None else y0
    x1 = w if x1 is None else x1; y1 = h if y1 is None else y1
    xs = []; ys = []
    rows = collections.defaultdict(list)
    for y in range(y0, y1):
        for x in range(x0, x1):
            if pngtool.hx(pngtool.px(img, x, y)) != bg:
                xs.append(x); ys.append(y); rows[y].append(x)
    if not xs: print("no ink"); return
    print("ink bbox x=%d..%d (w=%d) y=%d..%d (h=%d) n=%d imgw=%d imgh=%d" % (
        min(xs), max(xs), max(xs)-min(xs)+1, min(ys), max(ys), max(ys)-min(ys)+1, len(xs), w, h))
    print("x-center=%.1f imgcenter=%.1f" % ((min(xs)+max(xs))/2, (w-1)/2))
    for y in sorted(rows):
        print("  y=%d: x=%d..%d n=%d" % (y, min(rows[y]), max(rows[y]), len(rows[y])))

def colgaps(f, ref, ):
    """column occupancy of diff vs ref -> glyph segmentation"""
    i1 = pngtool.load(f); i2 = pngtool.load(ref)
    w, h = i1[0], i1[1]
    cols = []
    for x in range(w):
        c = 0
        for y in range(h):
            if pngtool.px(i1, x, y) != pngtool.px(i2, x, y): c += 1
        cols.append(c)
    runs = []
    inrun = False
    for x in range(w):
        if cols[x] and not inrun: start = x; inrun = True
        elif not cols[x] and inrun: runs.append((start, x-1)); inrun = False
    if inrun: runs.append((start, w-1))
    print("segments (x0,x1,width):")
    prev = None
    for (s, e) in runs:
        gap = "" if prev is None else " gap_from_prev_start=%d" % (s - prev)
        print("  %d..%d w=%d%s" % (s, e, e-s+1, gap))
        prev = s

def glyph(f, ref, x0, x1, y0, y1):
    i1 = pngtool.load(f); i2 = pngtool.load(ref)
    for y in range(y0, y1+1):
        line = ""
        for x in range(x0, x1+1):
            p1 = pngtool.px(i1, x, y); p2 = pngtool.px(i2, x, y)
            if p1 == p2: line += "."
            else:
                # alpha of ink relative
                line += "#" if p1[0] > 200 else ("+" if p1[0] > 120 else "-")
        print("%4d %s" % (y, line))

if __name__ == '__main__':
    cmd = sys.argv[1]
    if cmd == 'd': diffbox(sys.argv[2], sys.argv[3])
    elif cmd == 'i': inkbox(sys.argv[2], sys.argv[3], *[int(v) for v in sys.argv[4:]])
    elif cmd == 'c': colgaps(sys.argv[2], sys.argv[3])
    elif cmd == 'g': glyph(sys.argv[2], sys.argv[3], *[int(v) for v in sys.argv[4:]])
